@extends('layouts.app') @section('page-title','My Appointments') @section('content')<div class="page-actions"><div><h2>Appointment history</h2><p class="muted">Cancel or reschedule within seven days of booking, before your consultation.</p></div><a class="btn btn-primary" href="{{ route('patient.appointments.book') }}">Book appointment</a></div><div class="table-card"><div class="table-scroll"><table><thead><tr><th>Reference</th><th>Patient</th><th>Doctor</th><th>Date & time</th><th>Fee</th><th>Status</th><th>Action</th></tr></thead><tbody>@forelse($appointments as $a)<tr><td>{{ $a->appointment_no }}</td><td>{{ $a->patient->full_name }}</td><td><strong>{{ $a->doctor->user->full_name }}</strong><small>{{ $a->doctor->specialty->specialty_name }}</small></td><td>{{ $a->slot?->slot_start?->format('d M Y h:i A') }}</td><td>Rs. {{ number_format($a->consultation_fee,2) }}</td><td><x-status :value="$a->status"/></td><td>@if($a->allowsPatientChanges())<div class="action-group"><a class="btn btn-secondary btn-sm" href="{{ route('patient.appointments.reschedule',$a) }}">Reschedule</a><form method="post" action="{{ route('patient.appointments.cancel',$a) }}" onsubmit="return confirm('Cancel this appointment?')">@csrf<input type="hidden" name="reason" value="Patient requested cancellation"><button class="btn btn-danger btn-sm">Cancel</button></form></div>@elseif(in_array($a->status,['BOOKED','CONFIRMED','RESCHEDULED']))<small class="muted">Changes no longer available</small>@else&mdash;@endif</td></tr>@empty<tr><td colspan="7">No appointment records.</td></tr>@endforelse</tbody></table></div></div>{{ $appointments->links() }}@endsection